import {kanaGroups,groupsFor,characterPool,getCharacterQuestion} from './characters.js';
import {animeQuotes,getAnimeQuestion} from './anime.js';
import {characterAnswerCard,characterNotice} from './character-card.js';
const levels=(T)=>[['beginner',T('Başlangıç','Beginner')],['intermediate',T('Orta','Intermediate')],['advanced',T('Zor','Advanced')]];
const labelFor=(value,T)=>Object.fromEntries(levels(T))[value] || T('Tümü','All');
export function translationBox(draft,u,prefix='main') {
 const {T,esc,icon}=u,language={tr:T('Türkçe','Turkish'),ja:T('Japonca','Japanese'),en:T('İngilizce','English')};
 const select=(name,value)=>`<label class="sr-only" for="${prefix}-${name}">${name==='source'?T('Kaynak dil','Source language'):T('Hedef dil','Target language')}</label><select id="${prefix}-${name}" name="${name}">${Object.entries(language).map(([id,label])=>`<option value="${id}" ${value===id?'selected':''}>${label}</option>`).join('')}</select>`;
 return `<section class="translation-container" data-prefix="${prefix}"><div class="section-top"><div><p class="eyebrow">${T('KELİMELER ARASINDA BİR KÖPRÜ','A BRIDGE BETWEEN WORDS')}</p><h2>${T('Çeviri masası','Translation desk')}</h2></div><span class="translator-badge">TR / 日本語 / EN</span></div><form data-form="translation"><div class="translation-languages">${select('source',draft.source)}<button type="button" data-action="translation-swap" class="swap-languages" aria-label="${T('Dilleri değiştir','Swap languages')}">⇄</button>${select('target',draft.target)}</div><label class="sr-only" for="${prefix}-text">${T('Çevrilecek metin','Text to translate')}</label><textarea id="${prefix}-text" name="text" rows="3" maxlength="500" placeholder="${T('Bir cümle yaz…','Write a sentence…')}" lang="${draft.source}">${esc(draft.text)}</textarea><div class="translation-bottom"><span class="translation-counter small muted">${new TextEncoder().encode(draft.text).length} / 500 ${T('bayt','bytes')}</span><button type="submit" class="btn primary" ${draft.busy?'disabled':''}>${draft.busy?T('Çevriliyor…','Translating…'):T('Çevir','Translate')}${icon('arrow')}</button></div><div data-translation-output aria-live="polite">${translationOutput(draft,u)}</div></form><p class="translation-disclosure">${T('MyMemory · Metin çevirmek için dış hizmete gönderilir ve sağlayıcı tarafından saklanabilir. İnternet gerekir. Sonuç otomatik bir öneridir.','MyMemory · Text is sent to an external service and may be retained by the provider. Internet required. Results are automatic suggestions.')} <a href="https://mymemory.translated.net/terms-and-conditions" target="_blank" rel="noopener noreferrer">${T('Hizmet koşulları','Service terms')} ↗</a></p></section>`;
}
export function translationOutput(draft,{T,esc}) {
 const errors={INVALID_PAIR:T('Farklı iki dil seç.','Choose two different languages.'),EMPTY_TEXT:T('Çevrilecek bir cümle yaz.','Enter a sentence to translate.'),TEXT_TOO_LONG:T('En fazla 500 UTF-8 bayt gönderilebilir. Japonca karakterler daha çok yer kaplar.','Maximum 500 UTF-8 bytes. Japanese characters use more bytes.'),ONE_PARAGRAPH:T('Bir seferde tek paragraf çevir.','Translate one paragraph at a time.'),QUOTA:T('Çeviri hizmetinin günlük kotası doldu. Daha sonra tekrar dene.','The translation service daily quota is exhausted. Try again later.'),TIMEOUT:T('Çeviri hizmeti zamanında yanıt vermedi. Tekrar deneyebilirsin.','The service did not respond in time. You can retry.'),NETWORK:T('Çeviri hizmetine ulaşılamadı. İnternetini ve yerel sunucuyu kontrol et.','Could not reach the translation service. Check your connection and local server.'),PROVIDER_ERROR:T('Çeviri hizmeti bu isteği tamamlayamadı. Tekrar deneyebilirsin.','The translation service could not complete this request. You can retry.')};
 if(draft.error)return `<p class="translation-error" role="alert">${esc(errors[draft.error] || errors.PROVIDER_ERROR)}</p>`;
 if(draft.result)return `<div class="translation-result"><span class="eyebrow">${T('ÇEVİRİ ÖNERİSİ','TRANSLATION SUGGESTION')}</span><p lang="${draft.target}">${esc(draft.result)}</p>${draft.route?.length===3?`<p class="small muted">${T('İngilizce üzerinden çevrildi: TR ↔ EN ↔ JA. Anlam kayması olabilir.','Translated via English: TR ↔ EN ↔ JA. Meaning may shift.')}</p>`:''}<button type="button" class="subtle-link" data-action="translation-copy">${T('Sonucu kopyala','Copy result')}</button></div>`;
 return `<div class="translation-placeholder">${T('Sonuç burada görünecek. Cevap anahtarı olarak kullanılmaz.','The result will appear here. It is not used as an exercise answer key.')}</div>`;
}
export function hubPage(state,u,draft) {
 const {T,esc,icon}=u;
 const scripts=[['hiragana','あ','Hiragana',T('46 temel karakterle başla.','Start with 46 basic characters.')],['katakana','ア','Katakana',T('Ödünç kelimeleri okumayı keşfet.','Learn to read loanwords.')],['kanji','漢','Kanji',T('Karakterleri kelimelerle öğren.','Learn characters through words.')]];
 return `<section class="study-hero"><div><p class="eyebrow">${T('KARAKTERDEN REPLİĞE, ADIM ADIM','FROM CHARACTERS TO DIALOGUE')}</p><h1 tabindex="-1">${T('Japoncanı<br>oynayarak geliştir.','Play your way<br>into Japanese.')}</h1><p>${T('Harfleri tanı, okunuşlarını hatırla. Sonra sevdiğin<br class="desktop-break"> animelerin cümlelerinde yakala.','Recognize the characters. Recall their readings.<br class="desktop-break"> Then find them in the anime you love.')}</p><div class="button-row"><a class="btn primary" href="#characters">${T('Harf bilmecesine başla','Start a character challenge')}${icon('arrow')}</a><a class="hero-secondary" href="#anime">${T('Animeyle çalış','Study with anime')} ↗</a></div></div><div class="kana-art" aria-hidden="true"><span>あ</span><span>ア</span><span>漢</span><i>まいにち、たのしく。</i></div></section>
 <div class="hub-grid"><section class="launch-panel"><div class="section-top"><div><p class="eyebrow">${T('BİR ALFABE SEÇ','PICK A SCRIPT')}</p><h2>${T('Bugün hangi karakterler?','Which characters today?')}</h2></div><span class="small muted">${T('Başlangıç → Orta → Zor','Beginner → Intermediate → Advanced')}</span></div><div class="script-launches">${scripts.map(([id,glyph,title,desc])=>`<button class="script-launch ${id}" data-action="quick-script" data-script="${id}"><span lang="ja">${glyph}</span><div><h3>${title}</h3><p>${desc}</p></div>${icon('arrow')}</button>`).join('')}</div><p class="small muted">${T('Satırlarını seç. Romajiyle cevapla, seçeneklerden bul veya Japonca yaz.','Choose your rows. Type romaji, pick an answer, or write Japanese.')}</p></section>${translationBox(draft,u,'home')}</div>
 <section class="anime-discovery"><div class="section-top"><div><p class="eyebrow">${T('SEVDİĞİN SAHNELERDEN ÖĞREN','LEARN FROM THE SCENES YOU LOVE')}</p><h2>${T('Repliği yakala. Anlamını keşfet.','Catch the line. Find its meaning.')}</h2></div><a href="#anime" class="subtle-link">${T('Anime köşesine git','Go to anime corner')}${icon('arrow')}</a></div><div class="anime-mini-grid">${animeQuotes.map(q=>`<button class="anime-mini ${q.theme}" data-action="open-quote" data-quote="${q.id}"><span class="anime-glyph" lang="ja">${({naruto:'忍',bleach:'斬',vinland:'旅',jjk:'呪'})[q.theme]}</span><span class="anime-mini-bottom"><strong>${q.series}</strong><small>${labelFor(q.level,T)} · ${T('Kesit + alıştırma','Clip + exercise')}</small></span><span class="mini-play">▷</span></button>`).join('')}</div></section>
 <div class="hub-bottom"><p>${icon('repeat')}${state.events.length} ${T('cevap kaydın var. Küçük tekrarlar da çalışmanın bir parçası.','answers recorded. Little reviews are part of practice, too.')}</p><a href="#review" class="subtle-link">${T('Tekrarlarım','My reviews')} →</a><a href="#library" class="subtle-link">${T('Kısa metinlerle oku','Read short texts')} →</a></div>`;
}
export function answerCard(question,event,u,{form='lab-answer',next='lab-next',practiceClass='',draft='',wrongForCurrent=false,sessionId=''}={}) {
 if(form==='lab-answer'&&!event)return characterAnswerCard(question,u,{draft,wrongForCurrent,sessionId});
 const {T,L,esc,icon}=u;
 return `<section class="exercise-card lab-question ${practiceClass}"><div class="section-top"><span class="level-pill">${question.skill==='reading'?T('Okunuş','Reading'):question.skill==='meaning'?T('Anlam','Meaning'):T('Yazılı cevap','Written answer')}</span><button class="report-link" data-action="report" data-question-id="${esc(question.id)}">${icon('flag')}${T('Sorun bildir','Report an issue')}</button></div><h2 id="${form}-prompt">${esc(L(question.prompt))}</h2><div class="lab-glyph ${question.character?.script==='kanji'?'kanji-word':''}" lang="ja">${esc(question.context)}</div>${question.character?.script==='kanji' && question.responseType!=='writing'?`<p class="glyph-context">${T('Odak kanji','Focus kanji')}: <span lang="ja">${question.character.glyph}</span> · ${esc(L(question.character.meaning))}</p>`:''}<form data-form="${form}" aria-labelledby="${form}-prompt">${question.choices?`<fieldset class="choices lab-choices" ${event?'disabled':''}><legend class="sr-only">${T('Cevabın','Your answer')}</legend>${L(question.choices).map((v,i)=>`<label class="choice"><input type="radio" name="answer" value="${esc(v)}" required ${event?.answer===v?'checked':''}><span class="choice-key">${i+1}</span><span>${esc(v)}</span></label>`).join('')}</fieldset>`:`<label class="answer-label" for="${form}-input">${T('Cevabın','Your answer')}</label><input id="${form}-input" class="answer-input" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" required maxlength="200" ${event?'disabled':''} value="${esc(event?.answer || '')}" placeholder="${question.normalization==='romaji'?T('Okunuşu yaz…','Type the reading…'):T('Japonca yaz…','Type in Japanese…')}">`}${event?'':`<button class="btn primary full-width" type="submit">${T('Kontrol et','Check answer')}${icon('check')}</button>`}</form>${event?`<div class="feedback ${event.correct?'correct':'incorrect'}" tabindex="-1" role="status"><strong>${event.correct?T('Doğru, böyle devam!','Correct, keep going!'):T('Bir sonraki denemeye bir ipucu.','A clue for your next try.')}</strong><p>${esc(L(question.explanation))}</p><p>${T('Kabul edilen','Accepted')}: <strong>${esc(L(question.answers).join(' / '))}</strong></p></div><button class="btn primary full-width" data-action="${next}">${T('Devam et','Continue')}${icon('arrow')}</button>`:''}</section>`;
}
export function charactersPage(state,u) {
 const {T,esc,icon}=u,c=state.practice,s=c.session,pool=characterPool(c);
 const scripts=[['hiragana','あ','Hiragana'],['katakana','ア','Katakana'],['kanji','漢','Kanji']];
 const event=s?.feedback?state.events.find(e=>e.id===s.feedback):null;
 const total=s?.ids.length || 0;
 const kanjiCounts=['beginner','intermediate','advanced'].map(level=>characterPool({...c,script:'kanji',level}).length);
 return `<div class="page-heading"><p class="eyebrow">${T('KARAKTER ATÖLYESİ','CHARACTER STUDIO')}</p><h1 tabindex="-1">${T('Bak. Hatırla. Bir daha dene.','Look. Recall. Try again.')}</h1><p class="muted">${T('RealKana’dan ilham alan pratik: hangi karakterleri çalışacağını sen seç.','Practice inspired by RealKana: choose the characters you want to study.')}</p></div><div class="character-layout"><aside class="practice-config"><div class="script-tabs" aria-label="${T('Yazı sistemi','Writing system')}">${scripts.map(([id,glyph,name])=>`<button data-action="lab-script" data-script="${id}" aria-pressed="${c.script===id}"><span lang="ja">${glyph}</span>${name}</button>`).join('')}</div><div class="practice-selects"><label>${T('Zorluk','Difficulty')}<select data-lab="level">${levels(T).map(([id,name])=>`<option value="${id}" ${c.level===id?'selected':''}>${name}</option>`).join('')}</select></label><label>${T('Alıştırma türü','Exercise type')}<select data-lab="mode"><option value="reading" ${c.mode==='reading'?'selected':''}>${T('Okunuşunu yaz','Type the reading')}</option><option value="choice" ${c.mode==='choice'?'selected':''}>${T('Doğru okunuşu seç','Choose the reading')}</option><option value="writing" ${c.mode==='writing'?'selected':''}>${T('Japonca yazarak cevapla','Type in Japanese')}</option></select></label><label>${T('Karakter yazı tipi','Character font')}<select data-lab="font"><option value="sans" ${c.font==='sans'?'selected':''}>${T('Sade','Sans serif')}</option><option value="serif" ${c.font==='serif'?'selected':''}>${T('Kitap yazısı','Book serif')}</option></select></label></div>
 <div class="pool-note">${pool.length} ${T('karakter / kelime seçili','characters / words selected')}</div>${c.script!=='kanji'?`<details class="character-chart" ${s?.phase==='exercise'?'':'open'}><summary>${T('Çalışma satırlarını seç','Choose practice rows')}</summary><div class="chart-actions"><button class="subtle-link" data-action="lab-all">${T('Tümünü seç','Select all')}</button><button class="subtle-link" data-action="lab-none">${T('Temizle','Clear')}</button></div><label class="toggle"><input type="checkbox" data-lab="showReadings" ${c.showReadings?'checked':''}>${T('Tabloda okunuşları göster','Show readings in the chart')}</label><div class="kana-rows">${groupsFor(c.level).map(g=>`<label class="kana-row ${c.groups.includes(g.id)?'checked':''}"><input type="checkbox" data-kana-group="${g.id}" ${c.groups.includes(g.id)?'checked':''}><span class="row-name">${g.id}</span><span class="row-glyphs">${g.entries.map(item=>`<span lang="ja">${item[c.script]}${c.showReadings?`<small lang="en">${item.key}</small>`:''}</span>`).join('')}</span></label>`).join('')}</div></details>`:`<p class="small muted">${T(`Başlangıç: ${kanjiCounts[0]} kelime. Orta: ${kanjiCounts[1]} kelime. Zor: ${kanjiCounts[2]} kelime; günlük hayat ve animeyle ilgili örnekler dahil. Her kanji kelime bağlamında sorulur.`,`Beginner: ${kanjiCounts[0]} words. Intermediate: ${kanjiCounts[1]}. Advanced: ${kanjiCounts[2]}, including daily-life and anime-related words. Kanji are tested in word context.`)}</p>`}<p id="lab-validation" class="validation" role="alert"></p><button class="btn primary full-width" data-action="lab-start" ${!pool.length?'disabled':''}>${s?T('Yeni tur başlat','Start a new round'):T('Bilmeceleri başlat','Start the challenge')}${icon('arrow')}</button><p class="small muted">${T('Her tur en fazla 10 soru. Ayar değişikliği sonraki turu etkiler. Seviye adları bu paketin kapsamıdır; JLPT puanı değildir.','Up to 10 questions per round. Settings apply to the next round. Difficulty labels describe this pack, not JLPT proficiency.')}</p></aside><div class="practice-stage ${c.font==='serif'?'serif-glyph':''}">${characterNotice(s,u)}${!s?`<section class="practice-welcome"><div class="welcome-characters" lang="ja">${scripts.find(x=>x[0]===c.script)[1]}</div><p class="eyebrow">${T('KÜÇÜK BİR TUR, BÜYÜK BİR ALIŞKANLIK','A LITTLE ROUND, A LASTING HABIT')}</p><h2>${T('Kendi karakter setinle başla.','Start with your own character set.')}</h2><p>${T('Soldan satırlarını seç; bir tur başlat. Yanlışlarını gerekçesiyle gör, sonra tekrar listende karşılaş.','Choose your rows and start a round. Get explanations for mistakes and meet them again in your reviews.')}</p></section>`:s.phase==='done'?characterSummary(s,state,u):`<div class="round-progress"><span>${labelFor(s.config.level,T)} · ${s.config.script}</span><span>${s.index+1} / ${total}</span></div><div class="round-track"><i style="width:${s.index/total*100}%"></i></div>${answerCard(getCharacterQuestion(s.ids[s.index]),event,u,{draft:s.draft,wrongForCurrent:s.wrongForCurrent,sessionId:s.id || s.startedAt})}<p class="practice-scope small muted">${T('Bu alıştırma karakter okunuşunu veya klavyeyle yazılı cevabı kaydeder. El yazısı, konuşma ve dinleme puanı vermez.','This records character reading or a typed answer. It does not score handwriting, speaking, or listening.')}</p>`}</div></div>`;
}
function characterSummary(s,state,{T,icon}) {
 const events=state.events.filter(e=>s.eventIds.includes(e.id)),wrong=[...new Map(events.filter(e=>!e.correct).map(e=>[e.questionId,e])).values()];
 return `<section class="practice-welcome"><div class="completion-icon">${icon('check')}</div><p class="eyebrow">${T('TUR TAMAMLANDI','ROUND COMPLETE')}</p><h2>${T('Bir adım daha attın.','Another step forward.')}</h2><p>${events.filter(e=>e.correct).length} / ${s.ids.length} ${T('doğru tamamlandı','completed correctly')} · ${events.filter(e=>e.revealed).length} ${T('cevap gösterildi. Yanlış denemeler de ilerlemene kaydedilir.','answers revealed. Incorrect attempts are recorded too.')}</p>${wrong.length?`<p>${T('Tekrar karşılaşacakların','Your next practice targets')}: <span lang="ja">${wrong.map(e=>getCharacterQuestion(e.questionId).character.display).join(' · ')}</span></p><button class="btn secondary" data-action="lab-mistakes">${T('Yanlışları şimdi çalış','Practice mistakes now')}</button>`:`<p>${T('Harika. Başka bir satır veya yazı sistemi deneyebilirsin.','Nice work. Try another row or script.')}</p>`}<a href="#review" class="subtle-link">${T('Tekrar planına bak','See your review schedule')} →</a></section>`;
}
export function animePage(state,u) {
 const {T,L,esc,icon}=u,a=state.anime,all=[...animeQuotes,...a.customQuotes],filtered=all.filter(q=>(a.level==='all'||q.level===a.level)&&(a.series==='all'||q.series===a.series));
 const active=filtered.find(q=>q.id===a.activeId)||filtered[0];
 const practice=a.practice && active?.id===a.practice.quoteId ? a.practice:null,event=practice?.feedback?state.events.find(e=>e.id===practice.feedback):null;
 return `<div class="page-heading"><p class="eyebrow">${T('ANİME KÖŞESİ','ANIME CORNER')}</p><h1 tabindex="-1">${T('Bir replikle aklında kalsın.','Make it stick with a line.')}</h1><p class="muted">${T('Naruto · Bleach · Vinland Saga · Jujutsu Kaisen. Kısa alıntılar, resmî video kaynakları ve pratik. Spoiler içerebilir.','Naruto · Bleach · Vinland Saga · Jujutsu Kaisen. Short excerpts, official video sources, and practice. May contain spoilers.')}</p></div><div class="anime-filter"><label>${T('Anime','Anime')}<select data-anime="series"><option value="all">${T('Hepsi','All')}</option>${[...new Set(all.map(q=>q.series))].map(series=>`<option value="${esc(series)}" ${a.series===series?'selected':''}>${esc(series)}</option>`).join('')}</select></label><label>${T('Zorluk','Difficulty')}<select data-anime="level"><option value="all">${T('Hepsi','All')}</option>${levels(T).map(([value,label])=>`<option value="${value}" ${a.level===value?'selected':''}>${label}</option>`).join('')}</select></label><button class="subtle-link" data-action="add-quote">+ ${T('Kendi repliğini ekle','Add your own line')}</button></div><p class="small muted">${T('Seviye etiketleri soru desteğini ve yapı zorluğunu anlatır; replikler standart ders dili değildir.','Difficulty reflects task support and language complexity; character speech is not standard textbook language.')}</p>${!active?`<div class="empty-state"><h2>${T('Bu filtrede henüz replik yok.','No lines match these filters.')}</h2><button data-action="anime-reset" class="btn secondary">${T('Tüm replikleri göster','Show all lines')}</button></div>`:`<div class="anime-layout"><aside class="quote-list">${filtered.map(q=>`<button data-action="select-quote" data-quote="${q.id}" class="quote-choice ${q.id===active.id?'active':''} ${q.theme}"><span class="quote-series">${esc(q.series)}<small>${labelFor(q.level,T)}</small></span><span lang="ja">${esc(q.text)}</span><small>${esc(q.speaker)}</small></button>`).join('')}</aside><div class="quote-stage"><section class="quote-detail ${active.theme}"><div class="section-top"><span class="eyebrow">${esc(active.series.toUpperCase())} · ${esc(active.publisher)}</span><span class="level-pill">${labelFor(active.level,T)}</span></div><h2 lang="ja">${esc(active.text)}</h2><p lang="ja" class="quote-reading">${esc(active.reading)}</p><p class="quote-translation">${esc(L(active.translation))}</p><p class="quote-note">${esc(L(active.note))}</p><div class="button-row">${active.videoId?`<button class="btn primary" data-action="load-clip" data-quote="${active.id}">▷ ${T('Kesiti aç','Open clip')}</button>`:''}<button class="btn secondary" data-action="quote-practice" data-quote="${active.id}">${T('Bu replikle pratik yap','Practice this line')}${icon('arrow')}</button>${active.source?`<a class="subtle-link" href="${esc(active.source)}" target="_blank" rel="noopener noreferrer">${T('Kaynak','Source')} ↗</a>`:''}</div></section><section class="video-panel" id="video-panel" data-quote-id="${active.id}"><div class="video-placeholder"><span>▷</span><h3>${T('Repliği sahnesinde gör.','See the line in its scene.')}</h3><p>${T('“Kesiti aç” ile yayıncının YouTube oynatıcısı yüklenir.','“Open clip” loads the publisher’s YouTube player.')}</p></div></section><p class="small muted video-note">${T('Video ve altyazılar yayıncıdan gelir; bölge veya gömme kısıtları olabilir. Türkçe/Japonca çalışma metni uygulamanın ayrı notudur. Yalnızca zamanlaması doğrulanan kısa satırda eşzamanlı altyazı gösterilir.','Video and captions come from the publisher and may have regional or embedding restrictions. Turkish/Japanese study text is a separate app note. Synchronized captions are shown only for a short line with verified timing.')}</p>${practice?answerCard(getAnimeQuestion(`anime:${active.id}`,a.customQuotes),event,u,{form:'quote-answer',next:'quote-finish',practiceClass:'quote-exercise'}):''}</div></div>`}`;
}
